import React from 'react';

interface CharacterDetailProps {
  character: any;
  relationshipTypes: any[];
  onClose: () => void;
}

const CharacterDetail: React.FC<CharacterDetailProps> = ({ 
  character, 
  relationshipTypes,
  onClose 
}) => {
  if (!character) return null;

  // 获取关系类型的颜色
  const getRelationshipColor = (type: string) => {
    const relType = relationshipTypes.find(t => t.type === type);
    return relType ? relType.color : '#999999';
  };

  return (
    <div className="bg-white rounded-lg shadow-lg overflow-hidden">
      <div className="relative">
        {/* 关闭按钮 */}
        <button 
          onClick={onClose}
          className="absolute top-2 right-2 bg-white rounded-full p-1 shadow-md hover:bg-gray-100 transition-colors"
          aria-label="关闭"
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-gray-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
          </svg>
        </button>

        {/* 角色头像和基本信息 */}
        <div className="bg-gradient-to-r from-blue-500 to-purple-600 p-6 text-white">
          <div className="flex items-center">
            <div className="w-24 h-24 rounded-full border-4 border-white overflow-hidden bg-gray-200 flex-shrink-0">
              {character.avatar ? (
                <img 
                  src={`/images/characters/${character.avatar}`} 
                  alt={character.name} 
                  className="w-full h-full object-cover"
                />
              ) : (
                <div className="w-full h-full flex items-center justify-center text-gray-500 text-2xl font-bold">
                  {character.name.charAt(0)}
                </div>
              )}
            </div>
            <div className="ml-6">
              <h2 className="text-2xl font-bold">{character.name}</h2>
              <p className="text-blue-100 mt-1">{character.title}</p>
              <div className="mt-2 inline-block px-3 py-1 bg-white bg-opacity-20 rounded-full text-sm">
                修为: {character.cultivation}
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* 角色描述 */}
      <div className="p-6">
        <h3 className="text-lg font-semibold text-gray-800 mb-2">人物简介</h3>
        <p className="text-gray-600">{character.description}</p>

        {/* 关系列表 */}
        {character.relationships && character.relationships.length > 0 && (
          <div className="mt-6">
            <h3 className="text-lg font-semibold text-gray-800 mb-3">人物关系</h3>
            <div className="space-y-3">
              {character.relationships.map((rel: any, index: number) => (
                <div key={index} className="flex items-start">
                  <div 
                    className="w-3 h-3 rounded-full mt-1.5 flex-shrink-0"
                    style={{ backgroundColor: getRelationshipColor(rel.type) }}
                  ></div>
                  <div className="ml-3">
                    <div className="flex items-center">
                      <span className="font-medium text-gray-800">{rel.target}</span>
                      <span 
                        className="ml-2 px-2 py-0.5 rounded-full text-xs"
                        style={{ 
                          backgroundColor: `${getRelationshipColor(rel.type)}20`, 
                          color: getRelationshipColor(rel.type)
                        }}
                      >
                        {rel.type}
                      </span>
                    </div>
                    <p className="text-sm text-gray-600 mt-0.5">{rel.description}</p>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* 修炼信息 */}
        <div className="mt-6 p-4 bg-gray-50 rounded-lg">
          <h3 className="text-lg font-semibold text-gray-800 mb-2">修炼信息</h3>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <p className="text-sm text-gray-500">当前境界</p>
              <p className="font-medium text-gray-800">{character.cultivation}</p>
            </div>
            <div>
              <p className="text-sm text-gray-500">主要功法</p>
              <p className="font-medium text-gray-800">{character.id === 'hanlixiu' ? '青元剑诀' : '未知'}</p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default CharacterDetail;
